mapper.select:
SELECT ev.id, ev.tenant_code, ev.event_type, ev.detail, ev.request_uri, ev.request_method, ev.client_ip, ev.token_tenant, ev.operator_name, ev.event_time, ev.handle_status, ev.handle_remark, ev.handler_name, ev.handle_time, e.company_name FROM tenant_security_event ev LEFT JOIN tenant t ON t.tenant_code = ev.tenant_code AND t.is_deleted = FALSE LEFT JOIN enterprise e ON e.id = t.enterprise_id AND e.is_deleted = FALSE WHERE 1 = 1
AND ev.event_type = #{eventType}
AND ev.handle_status = #{handleStatus}
AND ev.tenant_code ILIKE '%' || #{tenantCode} || '%'
ORDER BY ev.event_time DESC, ev.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM tenant_security_event ev WHERE 1 = 1

   AND ev.event_type = #{eventType}


   AND ev.handle_status = #{handleStatus}


   AND ev.tenant_code ILIKE '%' || #{tenantCode} || '%'
